                // can still afford SOME approach (>= MIN_APPROACH_TIME). Once they can no
                // longer afford any, the round is allowed through (it yields no discovery in
                // calculateResults) so they can never be soft-locked before the action phase.
                if (timeCost > timeLeft && timeLeft >= this.MIN_APPROACH_TIME) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('time_warning'), 'warning'
                    );
                    return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var isActionPhase = period >= 7;

            var roundScore = 0;
            var finding = '';
            var timeCost = 0;

            if (isActionPhase) {
                var actionInfo = this.ACTION_DATA.find(function(a) { return a.id === d.action; });
                if (actionInfo) {
                    ds.budgetUsed += d.budget;
                    ds.selectedActions.push(d.action);

                    var discoveryLevel = 0;
                    if (actionInfo.rootCause === 'A') discoveryLevel = ds.rootCauseA;
                    if (actionInfo.rootCause === 'B') discoveryLevel = ds.rootCauseB;
                    if (actionInfo.rootCause === 'C') discoveryLevel = ds.rootCauseC;

                    var effectivenessMultiplier = 0.25;
                    if (discoveryLevel >= 70) effectivenessMultiplier = 1.0;
                    else if (discoveryLevel >= 40) effectivenessMultiplier = 0.6;

                    var budgetEfficiency = Math.min(d.budget / (actionInfo.cost || 1), 2.0);
                    var grossScore = Math.round(actionInfo.impact * effectivenessMultiplier * Math.min(budgetEfficiency, 1.2));
                    // 1.2.0: money above the saturation point (1.2 x implementation cost) is spent and buys nothing,
                    // so it comes off the recovery instead of being free (TN 019 Q4 and section 13: over-funding)
                    var wastedK = Math.max(0, d.budget - 1.2 * actionInfo.cost);
                    roundScore = Math.max(0, grossScore - Math.round(wastedK * this.WASTE_PER_K));
                    ds.wastedBudget = (ds.wastedBudget || 0) + wastedK;
                    ds.actionLog = (ds.actionLog || []).concat([{ action: d.action, budget: d.budget, cause: actionInfo.rootCause, level: discoveryLevel, gross: grossScore, net: roundScore, best: Math.round(actionInfo.impact * 1.2), wastedK: wastedK }]);
                    ds.actionScore += roundScore;

                    var ebitdaImpact = roundScore / 50;
                    ds.ebitdaRecovery = Math.min(ds.ebitdaRecovery + ebitdaImpact, 100);

                    finding = 'finding_action';
                }
            } else {
                timeCost = this.APPROACH_TIME[d.approach] || 10;
                var outOfTime = timeCost > ds.timeRemaining; // cannot afford it: forced no-op round
                ds.timeRemaining = Math.max(0, ds.timeRemaining - timeCost);

                if (ds.visitedModules.indexOf(d.module) === -1) {
                    ds.visitedModules.push(d.module);
                }
                var prevDepth = ds.moduleBestDepth[d.module] || 0;

                // Compute discovery with the PRIOR best depth so the first visit at a given
                // depth earns full gains and only genuine re-visits are diminished. The
                // moduleBestDepth update is deliberately performed AFTER this call. (It used
                // to run before, so _calculateDiscovery always saw prevDepth >= approach and
                // cut every analysis to 30% -> no root cause could ever reach 70 and the sim
                // was unwinnable.)
                var discoveryGains = outOfTime
                    ? { a: 0, b: 0, c: 0 }
                    : this._calculateDiscovery(d.module, d.approach, ds);

                if (d.approach > prevDepth) {
                    ds.moduleBestDepth[d.module] = d.approach;
                }

                ds.rootCauseA = Math.min(100, ds.rootCauseA + discoveryGains.a);
                ds.rootCauseB = Math.min(100, ds.rootCauseB + discoveryGains.b);
                ds.rootCauseC = Math.min(100, ds.rootCauseC + discoveryGains.c);

                var newCausesFound = 0;
                if (ds.rootCauseA >= 70) newCausesFound++;
                if (ds.rootCauseB >= 70) newCausesFound++;
                if (ds.rootCauseC >= 70) newCausesFound++;
                ds.causesFound = newCausesFound;

                roundScore = discoveryGains.a + discoveryGains.b + discoveryGains.c;
                // 1.2.0: a round that could not happen (out of time) earns nothing (TN 019 section 12.1)
                if (!outOfTime) {
                    roundScore += (d.approach - 1) * 3;
                    if (ds.visitedModules.length >= 3) roundScore += 5;
                }
                ds.investLog = (ds.investLog || []).concat([{ module: d.module, approach: d.approach, prevDepth: prevDepth, outOfTime: outOfTime, gain: discoveryGains.a + discoveryGains.b + discoveryGains.c, minutes: outOfTime ? 0 : timeCost }]);

                var findingKey = d.module + '_' + d.approach;
                finding = outOfTime ? 'finding_out_of_time'
                                    : (this.FINDINGS_MAP[findingKey] || 'finding_default');
            }

            if (!isActionPhase) ds.analyticalScore += roundScore; // action score lives in actionScore only (was double-counted into totalScore during the action phase)
            ds.totalScore = ds.analyticalScore + ds.actionScore;
            ds.lastFinding = finding;

            // 1.2.0 grade: one composite (diagnosis + matched and sized actions) and one tier function,
            // shared by the platform score, the verdict and the debrief
            var overallScore = this._composite(ds);
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });
            ds.performanceTier = this._tier(overallScore);

            ds.scoreHistory.push(ds.totalScore);
            ds.causeAHistory.push(ds.rootCauseA);
            ds.causeBHistory.push(ds.rootCauseB);
            ds.causeCHistory.push(ds.rootCauseC);

            this._updateProgressBars(ds);

            var findingsEl = document.getElementById('findingsText');
            if (findingsEl) {
                findingsEl.innerHTML = window.mySimulation.t(finding);
            }

            return {
                period: period,
                module: d.module,
                approach: d.approach,
                action: d.action,
                budget: d.budget,
                timeCost: timeCost,
                timeRemaining: ds.timeRemaining,
                roundScore: roundScore,
                totalScore: ds.totalScore,
                rootCauseA: ds.rootCauseA,
                rootCauseB: ds.rootCauseB,
                rootCauseC: ds.rootCauseC,
                causesFound: ds.causesFound,
                ebitdaRecovery: ds.ebitdaRecovery,
                overallScore: overallScore,
                score: overallScore
            };
        }

        // Diagnosis: 30 per confirmed cause (>= 70), 8 per partial cause (40-69), a trace below 40.
        // Actions: up to 16 per action round, in proportion to what the action recovered against the most it
        // could recover (confirmed cause, funded at 1.2 x cost, nothing wasted). Max reachable 100.
        _causeCredit(level) {
            if (level >= 70) return 30;
            if (level >= 40) return 8;
            return Math.round(level) / 10;
        }

        _composite(ds) {
            var diag = this._causeCredit(ds.rootCauseA || 0) + this._causeCredit(ds.rootCauseB || 0) + this._causeCredit(ds.rootCauseC || 0);
            var act = 0;
            (ds.actionLog || []).forEach(function(a) { act += a.best > 0 ? 16 * a.net / a.best : 0; });
            return Math.max(0, Math.min(100, Math.round((diag + act) * 10) / 10));
        }

        _tier(score) {
            if (score >= 85) return 'Excellent';
            if (score >= 75) return 'Proficient';
            if (score >= 45) return 'Competent';
            return 'Developing';
        }

        _num(v) {
            var l = '';
            try { l = (window.vcI18n && window.vcI18n._lang) || document.documentElement.lang || 'en'; } catch (e) { l = 'en'; }
            var txt = String(v);
            return String(l).slice(0, 2) === 'es' ? txt.replace('.', ',') : txt;
        }

        _fmt(str, params) {
            var self = this;
            return String(str).replace(/\{(\w+)\}/g, function(m, k) {
                if (!params || params[k] == null) return m;
                return typeof params[k] === 'number' ? self._num(params[k]) : params[k];
            });
        }

        // Run-specific debrief built from the run history: the mistakes of TN 019 sections 7 and 13 are named
        // only when they were made, never otherwise.
        _debrief(ds) {
            var self = this;
            var inv = ds.investLog || [], acts = ds.actionLog || [];
            var levels = { A: ds.rootCauseA || 0, B: ds.rootCauseB || 0, C: ds.rootCauseC || 0 };
            var confirmed = [], partial = [];
            ['A', 'B', 'C'].forEach(function(c) { if (levels[c] >= 70) confirmed.push(c); else if (levels[c] >= 40) partial.push(c); });
            var items = [], turning = null;
            var mark = function(round, key, params) { if (!turning || round < turning.round) turning = { round: round, key: key, params: params || {} }; };
            var revisits = [], opsMin = 0, opsRounds = [], oot = [];
            inv.forEach(function(r, i) {
                if (r.outOfTime) oot.push(i + 1);
                else if (r.prevDepth >= r.approach) revisits.push(i + 1);
                if (r.module === 4 && !r.outOfTime) { opsMin += r.minutes; opsRounds.push(i + 1); }
            });
            if (partial.length >= 2) { items.push({ k: 'dbf_spread', p: { n: partial.length, list: partial.map(function(c) { return c + ' ' + levels[c] + '%'; }).join(', ') } }); }
            if (revisits.length) { items.push({ k: 'dbf_revisit', p: { n: revisits.length, rounds: revisits.join(', ') } }); mark(revisits[0], 'tp_revisit', { r: revisits[0] }); }
            if (opsMin >= 15) { items.push({ k: 'dbf_ops', p: { m: opsMin } }); mark(opsRounds[0], 'tp_ops', { r: opsRounds[0] }); }
            if (oot.length) { items.push({ k: 'dbf_oot', p: { n: oot.length } }); mark(oot[0], 'tp_oot', { r: oot[0] }); }
            acts.forEach(function(a, j) {
                var rnd = inv.length + j + 1;
                if (!a.cause) { items.push({ k: 'dbf_nocause', p: { r: rnd } }); mark(rnd, 'tp_unconfirmed', { r: rnd }); }
                else if (a.level < 70) { items.push({ k: 'dbf_unconfirmed', p: { r: rnd, c: a.cause, l: a.level, pct: a.level >= 40 ? 60 : 25 } }); mark(rnd, 'tp_unconfirmed', { r: rnd }); }
            });
            var wasted = Math.round(ds.wastedBudget || 0);
            if (wasted > 0) { items.push({ k: 'dbf_overfund', p: { k: wasted } }); }
            var under = acts.filter(function(a) { return a.cause && a.net < a.best * 0.8 && a.wastedK === 0 && a.level >= 70; });
            if (under.length) { items.push({ k: 'dbf_underfund', p: { n: under.length } }); }
            if (inv.length >= 6 && (ds.timeRemaining || 0) >= 10) { items.push({ k: 'dbf_unspent', p: { m: ds.timeRemaining } }); }
            var good = [];
            if (confirmed.length >= 1 && !revisits.length) good.push({ k: 'dbg_ladder', p: { list: confirmed.join(' + ') } });
            if (acts.length && acts.every(function(a) { return a.cause && a.level >= 70 && a.wastedK === 0 && a.net >= a.best * 0.8; })) good.push({ k: 'dbg_actions', p: {} });
            if (confirmed.length === 2) good.push({ k: 'dbg_two', p: {} });
            var out = items.concat(good).slice(0, 4);
            out.push({ k: 'dbx_grade', p: { g: this._composite(ds), s: ds.totalScore || 0 } });
            if (!turning) {
                var first = 0;
                (ds.causeAHistory || []).forEach(function(v, i) {
                    var any = v >= 70 || (ds.causeBHistory || [])[i] >= 70 || (ds.causeCHistory || [])[i] >= 70;
                    if (any && !first) first = i + 1;
                });
                turning = first ? { round: first, key: 'tp_confirm', params: { r: first } } : { round: 0, key: 'tp_none', params: {} };
            }
            return { confirmed: confirmed, partial: partial, items: out, turning: turning };
        }

        _calculateDiscovery(module, approach, ds) {
            var a = 0, b = 0, c = 0;
            var hasVisitedCommercial = ds.visitedModules.indexOf(2) !== -1;
            var hasVisitedFinancial = ds.visitedModules.indexOf(5) !== -1;
            var crossRefBonus = (hasVisitedCommercial && hasVisitedFinancial) ? 1.3 : 1.0;

            if (module === 1) {
                if (approach === 1) { a = 8; }
                if (approach === 2) { a = 14; b = 5; }
                if (approach === 3) { a = 18; b = 8; c = 3; }
            } else if (module === 2) {
                if (approach === 1) { b = 6; }
                if (approach === 2) { b = 10; c = 12; }
                if (approach === 3) { b = 14; c = Math.round(22 * crossRefBonus); }
            } else if (module === 3) {
                if (approach === 1) { a = 18; }
                if (approach === 2) { a = 35; }
                if (approach === 3) { a = 45; b = 5; }
            } else if (module === 4) {
                if (approach === 1) { a = 2; b = 2; c = 2; }
                if (approach === 2) { a = 3; b = 3; c = 3; }
                if (approach === 3) { a = 5; b = 5; c = 5; }
            } else if (module === 5) {
                if (approach === 1) { a = 8; b = 8; }
                if (approach === 2) { b = 18; c = 10; }
                if (approach === 3) { b = 25; c = Math.round(28 * crossRefBonus); }
            }

            var prevDepth = ds.moduleBestDepth[module] || 0;
            if (prevDepth >= approach) {
                var diminish = 0.3;
                a = Math.round(a * diminish);
                b = Math.round(b * diminish);
                c = Math.round(c * diminish);
            }

            return { a: a, b: b, c: c };
        }

        _updateProgressBars(ds) {
            var barA = document.getElementById('causeABar');
            var barB = document.getElementById('causeBBar');
            var barC = document.getElementById('causeCBar');
            if (barA) { barA.style.width = ds.rootCauseA + '%'; barA.textContent = ds.rootCauseA + '%'; }
            if (barB) { barB.style.width = ds.rootCauseB + '%'; barB.textContent = ds.rootCauseB + '%'; }
            if (barC) { barC.style.width = ds.rootCauseC + '%'; barC.textContent = ds.rootCauseC + '%'; }
            [[barA, ds.rootCauseA], [barB, ds.rootCauseB], [barC, ds.rootCauseC]].forEach(function(p) {
                if (p[0] && typeof p[0].setAttribute === 'function') {
                    p[0].setAttribute('aria-valuenow', String(p[1] || 0));
                    p[0].setAttribute('aria-valuetext', (p[1] || 0) + '%' + ((p[1] || 0) >= 70 ? ' \u2713' : ''));
                }
            });
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var isActionPhase = period >= 7;

            var invControls = document.getElementById('investigationControls');
            var actControls = document.getElementById('actionControls');
            if (invControls) invControls.style.display = isActionPhase ? 'none' : 'block';
            if (actControls) actControls.style.display = isActionPhase ? 'block' : 'none';

            var phaseEl = document.getElementById('phaseTitle');
            var briefEl = document.getElementById('briefingText');

            if (period <= 2) {
                if (phaseEl) phaseEl.textContent = window.mySimulation ? window.mySimulation.t('phase_explore_title') : 'Phase 1: Exploration';
                if (briefEl) briefEl.innerHTML = window.mySimulation ? (window.mySimulation.t('briefing_initial') + '<br><br>' + window.mySimulation.t('phase_explore_text')) : '';
            } else if (period <= 4) {
                if (phaseEl) phaseEl.textContent = window.mySimulation ? window.mySimulation.t('phase_diagnose_title') : 'Phase 2: Diagnostic';
                if (briefEl) briefEl.innerHTML = window.mySimulation ? window.mySimulation.t('phase_diagnose_text') : '';
            } else if (period <= 6) {
                if (phaseEl) phaseEl.textContent = window.mySimulation ? window.mySimulation.t('phase_deep_title') : 'Phase 3: Deep Analysis';
                if (briefEl) briefEl.innerHTML = window.mySimulation ? window.mySimulation.t('phase_deep_text') : '';
            } else {
                if (phaseEl) phaseEl.textContent = window.mySimulation ? window.mySimulation.t('phase_action_title') : 'Phase 4: Corrective Actions';
                if (briefEl) briefEl.innerHTML = window.mySimulation ? window.mySimulation.t('phase_action_text') : '';
            }

            var statusEl = document.getElementById('roundStatusText');
            if (statusEl && window.mySimulation) {
                var tr = window.mySimulation.t.bind(window.mySimulation);
                var dsx = state.domainState || {};
                var left = dsx.timeRemaining != null ? dsx.timeRemaining : 90;
                var note = period >= 1 && period <= 8 ? '<br><em>' + tr('round_note_' + period) + '</em>' : '';
                if (isActionPhase) {
                    statusEl.innerHTML = this._fmt(tr('round_status_action'), { r: period, n: 8 - period + 1 }) + note + '<br>' + tr('action_costs');
                } else {
                    statusEl.innerHTML = this._fmt(tr('round_status_invest'), { r: period, m: left, k: Math.max(0, 6 - period + 1) }) + note;
                }
            }

            if (state.domainState) {
                this._updateProgressBars(state.domainState);
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('timeDisplay', 'domainState.timeRemaining', function(v) { return v + ' min'; });
            uiManager.bind('scoreDisplay', 'domainState.totalScore');
            uiManager.bind('causesDisplay', 'domainState.causesFound', function(v) { return v + ' / 3'; });
            uiManager.bind('ebitdaDisplay', 'domainState.ebitdaRecovery', function(v) { return Math.round(v) + '%'; });
            this._wireEvents();
        }

        _wireEvents() {
            if (this._eventsWired) return;
            this._eventsWired = true;
            var self = this;
            var sim = window.mySimulation;
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function') {
                // Render briefing/controls for the LIVE period after each submit. The
                // framework has already advanced currentPeriod, so we render for it
                // directly (no +1). Replaces the old setTimeout that rendered one period
                // ahead and flipped to the action phase a round early.
                sim.eventBus.on('period:submitted', function() { self._renderLive(); });
                // On undo, if history is now empty, restore the documented defaults, then
                // re-render KPIs, progress bars and the briefing for the restored period.
                sim.eventBus.on('period:undone', function(state) {
                    if (state && (!state.history || state.history.length === 0)) {
                        self._resetDomainState(state);
                    }
                    self._renderLive();
                });
            }
            // Re-localize the dynamic briefing + last finding when the language changes.
            document.addEventListener('express:langchanged', function() { self._renderLive(); });
        }

        _renderLive() {
            var sim = window.mySimulation;
            if (!sim || !sim.state) return;
            this._updateBriefing(sim.state);
            var findingsEl = document.getElementById('findingsText');
            if (findingsEl && sim.state.domainState && sim.state.domainState.lastFinding) {
                findingsEl.innerHTML = sim.t(sim.state.domainState.lastFinding);
            }
        }

        _resetDomainState(state) {
            state.domainState = {
                timeRemaining: 90,
                rootCauseA: 0, rootCauseB: 0, rootCauseC: 0,
                causesFound: 0, analyticalScore: 0, actionScore: 0,
                ebitdaRecovery: 0, totalScore: 0,
                visitedModules: [], moduleBestDepth: {},
                selectedActions: [], budgetUsed: 0, lastFinding: '',
                scoreHistory: [], causeAHistory: [], causeBHistory: [], causeCHistory: []
            };
            if (window.mySimulation && typeof window.mySimulation.updateUI === 'function') {
                window.mySimulation.updateUI();
            }
            this._updateProgressBars(state.domainState);
            var findingsEl = document.getElementById('findingsText');
            if (findingsEl) findingsEl.innerHTML = '';
        }

        formatCompletionMessage(summary) {
            var sim = window.mySimulation;
            var t = function(k) { return sim ? sim.t(k) : k; };
            var self = this;
            var ds = (sim && sim.state && sim.state.domainState) || {};
            var causes = summary.causesFound || 0;
            var score  = summary.totalScore || 0;
            var ebitda = Math.round(summary.ebitdaRecovery || 0);
            var grade = summary.overallScore != null ? summary.overallScore : this._composite(ds);
            var perfKey = 'perf_' + this._tier(grade).toLowerCase();
            var deb = this._debrief(ds);
            var causeLine = causes === 3 ? t('insight_causes_3') : causes === 2 ? t('insight_causes_2') : causes === 1 ? t('insight_causes_1') : t('insight_causes_0');
            var insights = [causeLine].concat(deb.items.map(function(it) { return self._fmt(t(it.k), it.p); }));
            var insHtml = insights.map(function(s) { return '<li style="margin-bottom:6px;">' + s + '</li>'; }).join('');
            var tpHtml = '<div style="margin-top:14px;padding:10px 12px;border-left:4px solid #c0392b;background:#fdf2f0;color:#3a1d18;border-radius:6px;text-align:left;">' +
                '<strong>' + t('completion_turning') + '</strong> ' + this._fmt(t(deb.turning.key), deb.turning.params) + '</div>';
            var dqHtml = '<div style="margin-top:14px;text-align:left;"><h5 style="margin-bottom:8px;">' + t('completion_questions') + '</h5>' +
                '<ol style="padding-left:20px;margin:0;"><li style="margin-bottom:6px;">' + t('dq_1') + '</li><li>' + t('dq_2') + '</li></ol></div>';
            return '' +
              '<div style="background:linear-gradient(135deg,#1a3a5c 0%,#2c5f8a 100%);color:#fff;border-radius:14px;padding:24px;text-align:center;">' +
                '<div style="font-size:0.75rem;letter-spacing:1px;opacity:0.75;text-transform:uppercase;">' + t('completion_performance') + '</div>' +
                '<div style="font-size:1.7rem;font-weight:700;margin:6px 0 4px;">' + t(perfKey) + '</div>' +
                '<div style="font-size:1rem;margin:0 0 18px;">' + t('completion_grade') + ': <strong>' + this._num(grade) + ' / 100</strong></div>' +
                '<div style="display:flex;justify-content:center;gap:26px;flex-wrap:wrap;">' +
                  '<div><div style="font-size:1.6rem;font-weight:700;">' + causes + ' / 3</div><div style="font-size:0.74rem;opacity:0.85;">' + t('completion_causes') + '</div></div>' +
                  '<div><div style="font-size:1.6rem;font-weight:700;">' + score + '</div><div style="font-size:0.74rem;opacity:0.85;">' + t('completion_score') + '</div></div>' +
                  '<div><div style="font-size:1.6rem;font-weight:700;">' + ebitda + '%</div><div style="font-size:0.74rem;opacity:0.85;">' + t('completion_ebitda') + '</div></div>' +
                '</div>' +
              '</div>' +
              '<div style="margin-top:16px;">' +
                '<h5 style="margin-bottom:10px;">' + t('completion_insights') + '</h5>' +
                '<ul style="text-align:left;padding-left:20px;margin:0;">' + insHtml + '</ul>' +
              '</div>' + tpHtml + dqHtml;
        }

        getChartConfig() {
            var sim = window.mySimulation;
            var t = function(k, d) { var v = sim && typeof sim.t === 'function' ? sim.t(k) : k; return v && v !== k ? v : d; };
            return {
                scoreChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: t('chart_total', 'Analytical Score'),
                                data: [],
                                borderColor: '#1a3a5c',
                                backgroundColor: 'rgba(26,58,92,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.3
                            },
                            {
                                label: t('chart_a', 'Cause A (%)'),
                                data: [],
                                borderColor: '#3498db',
                                borderWidth: 2,
                                borderDash: [5, 5],
                                fill: false,
                                tension: 0.3,
                                yAxisID: 'y1'
                            },
                            {
                                label: t('chart_b', 'Cause B (%)'),
                                data: [],
                                borderColor: '#f39c12',
                                borderWidth: 2,
                                borderDash: [5, 5],
                                fill: false,
                                tension: 0.3,
                                yAxisID: 'y1'
                            },
                            {
                                label: t('chart_c', 'Cause C (%)'),
                                data: [],
                                borderColor: '#e74c3c',
                                borderWidth: 2,
                                borderDash: [5, 5],
                                fill: false,
                                tension: 0.3,
                                yAxisID: 'y1'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: t('chart_title', 'Investigation Progress') }
                        },
                        scales: {
                            y: { beginAtZero: true, position: 'left', title: { display: true, text: t('chart_y', 'Analytical Score') } },
                            y1: { beginAtZero: true, max: 100, position: 'right', title: { display: true, text: t('chart_y1', 'Discovery %') }, grid: { drawOnChartArea: false } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var dsc = (state && state.domainState) || {};
            var labels = (dsc.scoreHistory || []).map(function(_, i) { return 'R' + (i + 1); });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [
                        { data: dsc.scoreHistory || [] },
                        { data: dsc.causeAHistory || [] },
                        { data: dsc.causeBHistory || [] },
                        { data: dsc.causeCHistory || [] }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var results = last.results || {};
            var causesFound = results.causesFound || 0;
            var totalScore = results.totalScore || 0;
            var ebitda = results.ebitdaRecovery || 0;

            var sim = window.mySimulation;
            var ds = (sim && sim.state && sim.state.domainState) || {};
            var grade = results.overallScore != null ? results.overallScore : this._composite(ds);
            var performance = this._tier(grade);
            var perfKey = 'perf_' + performance.toLowerCase();
            var self = this;
            var t = function(k) { return sim && typeof sim.t === 'function' ? sim.t(k) : k; };
            var deb = this._debrief(ds);
            var insights = deb.items.map(function(it) { return self._fmt(t(it.k), it.p); });

            return {
                causesFound: causesFound,
                totalScore: totalScore,
                ebitdaRecovery: Math.round(ebitda),
                overallScore: grade,
                score: grade,
                performance: performance,
                performanceKey: perfKey,
                performanceLabel: t(perfKey),
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var period = state.currentPeriod || 1;
            if (period === 3 && state.domainState.visitedModules.length < 2) {
                return window.mySimulation.t('hint_explore_more');
            }
            if (period === 5 && state.domainState.causesFound === 0) {
                return window.mySimulation.t('hint_no_causes');
            }
            if (period >= 5 && state.domainState.timeRemaining < 20) {
                return window.mySimulation.t('hint_low_time');
            }
            if (period === 6 && state.domainState.causesFound < 2) {
                return window.mySimulation.t('hint_dig_deeper');
            }
            if (results.timeCost > 0 && state.domainState.timeRemaining < 15) {
                return window.mySimulation.t('hint_time_critical');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.period', label: 'Round', i18nKey: 'col_round' },
                { key: 'decisions.module', label: 'Module', i18nKey: 'col_module', formatter: function(v) { return v > 0 ? 'M' + v : '—'; } },
                { key: 'decisions.approach', label: 'Approach', i18nKey: 'col_approach', formatter: function(v) { return v > 0 ? 'L' + v : '—'; } },
                { key: 'decisions.action', label: 'Action', i18nKey: 'col_action', formatter: function(v) { return v > 0 ? 'A' + v : '—'; } },
                { key: 'results.roundScore', label: 'Score', i18nKey: 'col_score', formatter: function(v) { return '+' + v; } },
                { key: 'results.causesFound', label: 'Causes', i18nKey: 'col_causes', formatter: function(v) { return v + '/3'; } }
            ];
        }

